AutomationFilterConditionValueOption4Item: TypeAlias = str | float | bool

# С чем сравнивать: строка (до 500 знаков), число, true/false или null. Для `in` — список до 50 таких значений; для `gt`/`gte`/`lt`/`lte` — число; для остальных — одно значение. Для `exists` не нужно (false — проверить, что поля нет).
AutomationFilterConditionValue: TypeAlias = (
    str | float | bool | Sequence[AutomationFilterConditionValueOption4Item | None]
)

# Поле итога: вид значения и описание для ИИ.
AutomationOutputField: TypeAlias = (
    AutomationOutputFieldOption1
    | AutomationOutputFieldOption2
    | AutomationOutputFieldOption3
    | AutomationOutputFieldOption4
    | AutomationOutputFieldOption5
)

# Форма итога шага ИИ (только action: agent): имя поля → вид и описание, от 1 до 20 полей. ИИ в конце хода обязан отдать итог в этой форме; он проверяется по ней и приходит в запуске (output) и в вебхуке automation.run.completed. Видов значения нет текстовых нарочно: в итоге не может оказаться имени, ИИН/БИН, счёта или свободного текста. Не отдал или итог не прошёл проверку — output: null и пометка output_error, запуск при этом не падает.
AutomationOutputSpec: TypeAlias = Mapping[str, AutomationOutputField]

# Когда запускать: по событию хука, по расписанию, по событию внутри Tungo или только вручную. Вид — в kind.
AutomationScenarioInputTrigger: TypeAlias = (
    AutomationScenarioInputTriggerOption1
    | AutomationScenarioInputTriggerOption2
    | AutomationScenarioInputTriggerOption3
    | AutomationScenarioInputTriggerOption4
)

# Расписание запуска по Алматы. Пропущенный запуск (сервис был недоступен) догоняется одним запуском, а не пачкой за все пропущенные слоты.
AutomationSchedule: TypeAlias = (
    AutomationScheduleDaily | AutomationScheduleWeekly | AutomationScheduleMonthly | AutomationScheduleInterval
)
